gap: 0;
  inline-size: fit-content;

  /* - on mobile off canvas mode */
  &.mobile.off-canvas-mode {
    position: fixed;
    inset: 0;
    visibility: hidden;
    inline-size: 100%;
    pointer-events: none;
    z-index: 999;
    opacity: 1;
    transition: visibility var(--mobile-menu-transition-duration, 0.2s) ease-out;
  }

  /* - on mobile reveal mode */
  &.mobile.reveal-mode {
    inline-size: 100%;
    position: absolute;
    inset-block-start: 100%;
    inset-inline: 0;
    overflow: hidden;
    visibility: hidden;
    clip-path: polygon(0 0, 100% 0, 100% 0, 0 0);
    background-color: var(--mobile-menu-bg-color);
    transition: clip-path, visibility, transform, opacity;
    transition-duration: var(--mobile-menu-transition-duration, 0.2s);
    transition-timing-function: cubic-bezier(0.42, 0, 0.58, 1);

    .menu-wrapper__inner {
      overflow-y: auto;
      overflow-x: clip;
      transform: translateY(20px);
    }

    .nav {
      padding-block-end: var(--mobile-menu-padding-block);
    }
  }

  /* - on mobile AND on open */
  &.mobile.open {
    visibility: visible;
    opacity: 1;
  }

  /* - on mobile AND open AND reveal mode */
  &.mobile.reveal-mode.open {
    clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%);

    .menu-wrapper__inner {
      transform: translateY(0);
    }
  }

  /* HELPER CLASSES */

  /* - hide item on desktop */
  &.desktop :is(.hide-from-desktop-menu, [data-menu-hide='desktop']) {
    display: none;
  }

  /* - hide item on mobile */
  &.mobile :is(.hide-from-mobile-menu, [data-menu-hide='mobile']) {
    display: none;
  }

  /* hide menu until initialized */

  &:not([data-menu-initialized]) {
    opacity: 0;
  }

  /* MORPH MODE (desktop shared morphing container, JS-created) */
  .morph-container {
    position: absolute;
    inset-block-start: 100%;
    inset-inline-start: 0;
    z-index: 999;
    background: var(--dropdown-bg, white);
    box-shadow: var(--dropdown-box-shadow);
    border-radius: var(--dropdown-border-radius);
    border: var(--dropdown-border-width) solid var(--dropdown-border-color);
    visibility: hidden;
    opacity: 0;
    transform: translateY(var(--dropdown-closed-top, 40px));
    transition-property: opacity, transform, visibility, scale;
    transition-duration: var(--dropdown-transition-duration, 0.15s);
    transition-timing-function: var(--dropdown-transition-timing, cubic-bezier(0.4, 0, 0.2, 1));
    transition-delay: var(--dropdown-transition-delay, 0s);

    /* open / close */
    &.is-active {
      visibility: visible;
      opacity: 1;
      transform: translateY(var(--dropdown-open-top, 20px));
    }

    /* JS adds is-morphing while sliding between panels: the container box
       itself animates position and size, and clips the panel slide */
    &.is-morphing {
      overflow: clip;
      transition-property: opacity, transform, visibility, inset-inline-start, inline-size, block-size;
      transition-duration: var(--dropdown-transition-duration, 0.3s);
      transition-timing-function: var(--dropdown-transition-timing, cubic-bezier(0.4, 0, 0.2, 1));
    }

    /* panels: shown via is-active (the .is-open parent selector no longer
       applies once JS moves them into the shared container) */
    .menu-dropdown__content-wrapper.morph-panel {
      transition-property: opacity, visibility;

      &.is-active {
        visibility: visible;
        opacity: 1;
      }

      /* the shared container carries the dropdown chrome instead */
      > .menu-dropdown__content {
        background: transparent;
        box-shadow: none;
        border: none;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      transition: none;
    }
  }

